"""Build the editable page templates for the consultation-first website."""
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]/'web/templates'
BOOK='https://app.minup.io/book/stratevo'
CTA=f'<a class="primary" data-booking href="{BOOK}" target="_blank" rel="noopener noreferrer">Book a Sourcing Call <span aria-hidden="true">↗</span></a>'
FOCUSES=[('industrial','Industrial Components'),('packaging','Packaging & Materials'),('consumer','Consumer Products'),('food','Food & Ingredients'),('textiles','Textiles & Apparel'),('electronics','Electronics & Hardware'),('custom','Custom Manufacturing')]
def save(name,text): (ROOT/(name+'.content.html')).write_text(text)
def heading(kicker,title,description):return f'<section class="page-top"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro">{description}</p></section>'
def field(name,label,attrs='',prefix='register',textarea=False):
 tag=f'<textarea id="{prefix}-{name}" name="{name}" {attrs}></textarea>' if textarea else f'<input id="{prefix}-{name}" name="{name}" {attrs}>'
 return f'<div class="field"><label for="{prefix}-{name}">{label}</label>{tag}<p class="field-error" id="{prefix}-{name}-error" hidden></p></div>'
def profile_form(prefix):
 focus='<div class="field"><label for="'+prefix+'-focus">Focus area *</label><select id="'+prefix+'-focus" name="focus" required><option value="">Choose a focus area</option>'+''.join(f'<option value="{k}">{escape(v)}</option>' for k,v in FOCUSES)+'</select><p class="field-error" id="'+prefix+'-focus-error" hidden></p></div>'
 public=field('company','Supplier name *','required minlength="2" maxlength="120" autocomplete="organization"',prefix)+focus+field('specialty','Focus specialty (optional)','maxlength="160" placeholder="For example: precision aluminium components"',prefix)+field('description','Supplier description & capabilities *','required minlength="20" maxlength="2000" rows="6" aria-describedby="public-description-help"',prefix,True)
 private=field('contact','Contact person *','required minlength="2" maxlength="120" autocomplete="name"',prefix)+field('email','Business email *','required type="email" maxlength="254" autocomplete="email"'+(' readonly' if prefix=='edit' else ''),prefix)+field('phone','Phone number (optional)','type="tel" maxlength="80" autocomplete="tel"',prefix)+field('country','Country (optional)','maxlength="100" autocomplete="country-name"',prefix)+field('city','City (optional)','maxlength="100" autocomplete="address-level2"',prefix)+field('website','Company website (optional)','type="text" inputmode="url" maxlength="2000" placeholder="example.com"',prefix)
 return '<fieldset><legend>Public supplier listing</legend><p id="public-description-help">Only your supplier name, focus and description appear in the Marketplace. Keep personal contacts, web links and confidential information out of these fields.</p>'+public+'</fieldset><fieldset><legend>Private contact details</legend><p>Only you and authorized STRATEVO staff can view these details. They are not shown to Marketplace visitors.</p><div class="form-grid">'+private+'</div></fieldset><label class="check"><input id="'+prefix+'-consent" name="consent" type="checkbox" required><span>I confirm that the information provided is accurate and agree to the <a href="/terms">Terms</a> and <a href="/privacy">Privacy Policy</a>.</span></label><p class="field-error" id="'+prefix+'-consent-error" hidden></p>'

save('home','''<section class="hero"><div><p class="eyebrow">CHINA SOURCING · PERSONAL GUIDANCE</p><h1>Find the right manufacturer.<br><span>Know what to check.</span></h1><p class="intro">Sourcing support for e-commerce founders, resellers and businesses building products or private-label lines.</p><ul class="benefit-list"><li>Comparable quotations</li><li>Clearer supplier evidence</li><li>Organized next steps</li></ul>'''+CTA+'''<p class="small">Start with a conversation. Any paid engagement is agreed separately.</p></div><aside class="brief-visual" aria-label="An example sourcing brief, not a live project"><p class="eyebrow">A CLEARER SOURCING BRIEF</p><div class="brief-row"><span>01 / REQUIREMENT</span><strong>Product · quantity · destination</strong></div><div class="brief-row"><span>02 / COMPARISON</span><strong>Specifications · MOQ · quote scope</strong></div><div class="brief-row"><span>03 / CHECKS</span><strong>Evidence · samples · delivery</strong></div><p class="small">An organized decision—not a promise about a supplier.</p></aside></section>
<section class="section"><p class="eyebrow">HOW IT WORKS</p><h2>From a product idea<br>to an informed next step.</h2><div class="card-grid"><article class="panel"><span class="step">01</span><h3>Define the brief</h3><p>Talk through what you need, your budget, customization and delivery constraints.</p></article><article class="panel"><span class="step">02</span><h3>Compare on equal terms</h3><p>Separate quoted prices from tooling, samples, order quantities and shipping responsibilities.</p></article><article class="panel"><span class="step">03</span><h3>Check the evidence</h3><p>Identify what remains unverified and what should be checked before a commercial commitment.</p></article></div><a class="secondary" href="/methodology">See the evaluation process ↗</a></section>
<section class="section split"><div><p class="eyebrow">BEYOND A DIRECTORY</p><h2>A name is a starting point.<br>Evidence makes it useful.</h2><p>A listing tells you what a supplier says it does. A structured evaluation asks whether its capabilities, terms and supporting evidence fit your specific project.</p><a class="secondary" href="/methodology#comparison">Explore an illustrative comparison ↗</a></div><aside class="panel"><h3>Bring these to your call</h3><ul class="checklist"><li>A product image or specification you have rights to share</li><li>Your target quantity and destination</li><li>Budget and timeline, even if provisional</li><li>Custom branding or compliance requirements</li></ul>'''+CTA+'''</aside></section><section class="section split"><div><p class="eyebrow">FOR SUPPLIERS</p><h2>Make your capabilities clear.</h2><p>Create a public supplier introduction while keeping your personal contact details private. Interested buyers speak with STRATEVO first.</p></div><a class="secondary" href="/supplier">Register as a Supplier ↗</a></section>''')

save('supplier',heading('FOR SUPPLIERS','Introduce your business.','Join STRATEVO’s sourcing network with a clear supplier profile. Your name, focus and description appear publicly; contact details stay private.')+'''<div class="split align-start"><section class="panel"><h2>Register your supplier profile</h2><p>Required fields are marked *. One submission creates your account and publishes your supplier introduction. Registration does not guarantee orders or establish business verification.</p><p class="small">After registration, this browser keeps a copy of your public listing for account recovery checks. Private contacts and credentials are never included in that backup. You can clear it in your account.</p><form id="market-register" method="post">'''+profile_form('register')+'''<button type="submit" class="primary">Register &amp; Publish</button><p id="market-register-status" role="status" class="form-status"></p></form></section><aside><section class="panel"><h2>Questions before joining?</h2><p>Talk through your capabilities and how introductions work.</p>'''+CTA+'''</section></aside></div>''')
save('supplier-account',heading('SUPPLIER ACCOUNT','Manage your supplier profile.','Keep your public introduction and private contact details up to date.')+'''<section id="account-signin" class="panel narrow"><h2>Supplier Session Required</h2><p id="market-account-status" role="status">Checking whether you are signed in…</p><p>Use the browser where you registered to manage your listing. If your session has expired, contact STRATEVO for help verifying account ownership.</p><a class="primary" href="mailto:info@stratevo.store">Contact STRATEVO</a><button id="account-retry" class="secondary" type="button">Check Session Again</button></section><div id="account-root"></div><template id="account-template"><section id="market-account"><div class="panel"><h2>Supplier account</h2><p id="account-state" role="status"></p><p>Email changes require verification. Our team will be notified automatically when you update your profile.</p><div class="actions"><a class="secondary" href="/marketplace">View Marketplace</a><button id="withdraw-listing" type="button" class="secondary">Withdraw Listing</button><button id="market-logout" type="button" class="secondary">Sign Out</button></div></div><section class="panel"><h2>Edit your listing &amp; private profile</h2><p>Changes to your public name, focus and description are published when you save. Business email changes require contacting STRATEVO to verify ownership.</p><form id="directory-edit" method="post">'''+profile_form('edit')+'''<button class="primary" type="submit">Save &amp; Publish Changes</button><p id="directory-edit-status" role="status"></p></form></section></section></template>''')
save('marketplace',heading('SUPPLIER MARKETPLACE','Capabilities worth a conversation.','Explore supplier introductions. Profiles are self-reported—not independent verification, quotations or endorsements.')+CTA+'''<section class="panel filter-panel"><form id="market-filter" method="get"><div class="field"><label for="market-query">Search suppliers</label><input id="market-query" name="q" maxlength="100" placeholder="Name, material or capability"></div><div class="field"><label for="market-focus">Focus area</label><select id="market-focus" name="focus"><option value="">All focus areas</option>'''+''.join(f'<option value="{k}">{escape(v)}</option>' for k,v in FOCUSES)+'''</select></div><button type="submit" class="secondary">Search</button></form><p id="market-status" role="status"></p></section><div id="market-products" class="card-grid"></div><button id="market-more" type="button" class="secondary" hidden>Load More Suppliers</button><dialog id="supplier-detail" aria-labelledby="detail-name"><button id="detail-close" class="dialog-close" type="button" aria-label="Close supplier details">×</button><h2 id="detail-name" tabindex="-1"></h2><p id="detail-focus" class="badge"></p><p id="detail-description" class="preserve-lines"></p><a id="detail-booking" data-booking class="primary" href="https://app.minup.io/book/stratevo" target="_blank" rel="noopener noreferrer">Book a Sourcing Call for This Supplier ↗</a><p>Interested in working with this supplier? Book a sourcing call with STRATEVO to discuss specifications, pricing, and next steps.</p><a id="detail-report" class="text-link" href="mailto:info@stratevo.store?subject=Listing%20or%20IP%20report">Report a Listing / IP Infringement</a></dialog><section class="section"><h2>Report a listing or infringement</h2><p>Send the listing name and exact URL, explain the concern, identify any rights affected and include supporting evidence. For a formal notice, include your name and email and confirm that the information is accurate and complete to the best of your knowledge.</p><a class="secondary" href="mailto:info@stratevo.store?subject=Listing%20or%20IP%20report">Report a Listing / IP Infringement</a><a class="text-link" href="/terms#reporting">Read the notice and review procedure</a></section>''')
for page in ['assessment','inquiry']:
 save(page,heading('LET’S TALK SOURCING','Prepare for your sourcing call.' if page=='assessment' else 'Let’s talk about your sourcing project.','Skip the long form. Book a sourcing call to discuss your product, requirements and next steps.')+CTA+'''<section class="section"><h2>What to prepare</h2><div class="card-grid"><article class="panel"><h3>Your product</h3><p>Describe its purpose, materials, specifications and customization. Share only documents you have permission to disclose.</p></article><article class="panel"><h3>Your constraints</h3><p>Bring a quantity, budget, destination and target date. It is fine if some answers are not settled yet.</p></article><article class="panel"><h3>Your questions</h3><p>List uncertainties about samples, certifications, production, inspection and delivery.</p></article></div><p>Booking takes place on Minup. Opening the calendar does not create an order or a sourcing contract.</p><a class="text-link" href="mailto:info@stratevo.store">Prefer email? info@stratevo.store</a></section>''')
save('methodology',heading('HOW IT WORKS','Compare the requirement.<br>Then compare the suppliers.','STRATEVO helps businesses source and evaluate manufacturers in China. Our work begins with a specific brief—not a promise that a directory listing is a verified factory.')+CTA+'''<section class="section"><h2>Four steps, with a clear scope.</h2><ol class="process-grid"><li><h3>Define</h3><p>Product specifications, materials, volume, customization and destination requirements.</p></li><li><h3>Compare</h3><p>Like-for-like quotations, MOQ, tooling, samples, payment terms and delivery responsibilities.</p></li><li><h3>Check</h3><p>Business identity, relevant certificate scope, sample acceptance and any independent inspection required.</p></li><li><h3>Decide</h3><p>Record outstanding risks and agree next steps. Buyers and suppliers execute their own commercial contracts.</p></li></ol></section><section id="comparison" class="section"><p class="eyebrow">ILLUSTRATIVE ONLY · NOT REAL SUPPLIERS OR QUOTES</p><h2>Price is only one part of the comparison.</h2><p>These fictional examples demonstrate questions to ask. No supplier recommendation or scoring is produced.</p><label for="comparison-lens">What would you examine first?</label><select id="comparison-lens"><option value="scope">Quote scope</option><option value="moq">Minimum order quantity</option><option value="evidence">Evidence still needed</option></select><div class="card-grid"><article class="panel"><h3>Example A</h3><p>Unit price shown; tooling excluded.</p><p data-scope="scope">Ask for a complete cost breakdown.</p><p data-scope="moq">Illustrative MOQ: 500 units.</p><p data-scope="evidence">Request a production sample and agreed inspection criteria.</p></article><article class="panel"><h3>Example B</h3><p>Tooling included; shipping scope unclear.</p><p data-scope="scope">Clarify the delivery term, location and exclusions.</p><p data-scope="moq">Illustrative MOQ: 1,000 units.</p><p data-scope="evidence">Check the contracting entity and certificate scope.</p></article><article class="panel"><h3>Example C</h3><p>Small trial offered; repeat-order terms unset.</p><p data-scope="scope">Confirm trial and repeat-order specifications match.</p><p data-scope="moq">Illustrative MOQ: 100 units.</p><p data-scope="evidence">Agree an acceptance sample and repeat-order controls.</p></article></div><p id="comparison-status" role="status"></p></section><section class="section readable"><h2>Questions worth asking</h2><details><summary>Does listing a supplier mean it is verified?</summary><p>No. Finding a name, evaluating commercial fit and independently verifying a factory are different tasks. Profiles contain supplier-provided information. Any paid verification or inspection must have a separately agreed scope.</p></details><details><summary>What should a quotation include?</summary><p>Specifications and revision, quantity, currency, unit price, tooling, packaging, sample charges, payment terms, lead time, quote validity and delivery responsibilities. Compare totals only after aligning the scope.</p></details><details><summary>How should certifications be checked?</summary><p>Check the named legal entity, issuing body, certificate number, site, scope and validity. A certificate for one process or site does not establish compliance for every product.</p></details><details><summary>What does MOQ mean?</summary><p>The minimum order quantity a supplier is willing to accept for a specified product or configuration. Ask whether the minimum applies per material, size, color or total order.</p></details><details><summary>Who signs the purchase contract?</summary><p>The buyer and supplier. STRATEVO is an independent facilitator and research consultant, not the seller of the goods. Scope and fees for consulting are agreed separately.</p></details><h3>Primary references</h3><ul><li><a href="https://iccwbo.org/business-solutions/incoterms-rules/" rel="noopener noreferrer" target="_blank">ICC: delivery terms and responsibilities</a></li><li><a href="https://www.iso.org/certification.html" rel="noopener noreferrer" target="_blank">ISO: certification and independent certification bodies</a></li><li><a href="https://trade.ec.europa.eu/access-to-markets/en/home" rel="noopener noreferrer" target="_blank">European Commission: import requirements</a></li></ul>'''+CTA+'</section>')
operator='''<section id="operator"><h2>Legal &amp; Operator Information</h2><dl><dt>Operator</dt><dd>Vasilis Krevatsoulis, trading as STRATEVO</dd><dt>Contact email</dt><dd><a href="mailto:info@stratevo.store">info@stratevo.store</a></dd><dt>Phone</dt><dd><a href="tel:+306989472740">+30 6989472740</a></dd><dt>Business address</dt><dd>[Physical business address not supplied]</dd><dt>Registration / VAT</dt><dd>[Registration and VAT details, where applicable, not supplied]</dd></dl></section>'''
save('terms',heading('TERMS','Service scope &amp; website terms.','Last updated 19 October 2026. These terms describe the website and sourcing consultancy; any paid engagement requires a separate written scope.')+'<div class="readable legal">'+operator+'''<section><h2>Our role</h2><p>STRATEVO acts solely as an independent B2B sourcing facilitator and research consultant. STRATEVO is not a party to transactions between buyers and suppliers, does not take title to goods and makes no warranties regarding product quality, regulatory compliance or supplier performance. Buyers and suppliers execute their own commercial contracts after independent due diligence.</p><p>No website listing or booking is a binding quotation, purchase order, product endorsement or guarantee of business. Nothing in these terms excludes liability or rights that cannot lawfully be excluded.</p></section><section><h2>Supplier profiles</h2><p>Suppliers authorize public display of their business name, focus and description when registering. Personal contact information is kept private. Suppliers must provide accurate information and hold any rights needed to publish it. Do not include confidential designs, personal contacts, misleading claims or unlawful content in public text.</p><p>Profiles publish on registration and after authorized edits. Publication is not independent verification. STRATEVO may restrict accounts or remove listings for unlawful content, rights infringement, misleading information or violations of these terms. Removed listings cannot be reinstated by a browser backup.</p></section><section id="reporting"><h2>Notice, takedown &amp; review</h2><p><a href="mailto:info@stratevo.store?subject=Listing%20or%20IP%20report">Report a Listing / IP Infringement</a>. Please provide the exact listing URL and name, a sufficiently detailed explanation of the alleged illegality or inaccuracy, relevant rights and supporting evidence, your name and email, and a statement that the information is accurate and complete to the best of your knowledge. Do not attach unnecessary personal data. Where the law permits anonymous notices, contact details are not required.</p><p>We assess notices without undue delay and remove or restrict content where justified. A report is not automatic proof of infringement. Where contact details are provided, we acknowledge receipt and communicate the decision and available review options. Affected suppliers can request review by emailing the same address with their listing reference and supporting evidence. These requests are handled by a person; a court or competent authority may also provide redress where available.</p><p>Time-sensitive safety or illegal-content concerns should be identified clearly. Nothing here limits legal remedies. The operator must maintain an adequately monitored reporting mailbox and apply the procedure consistently.</p></section><section><h2>Booking and service fees</h2><p>Consultations are scheduled through Minup. Paid sourcing work starts only after the parties agree a written proposal describing deliverables, exclusions, fees and responsibilities. The website does not collect payment for goods.</p></section></div>''')
save('privacy',heading('PRIVACY','Your information, handled for a clear purpose.','Last updated 19 October 2026.')+'<div class="readable legal">'+operator+'''<section><h2>Data we process and why</h2><ul><li><strong>Supplier accounts:</strong> business name, focus, description, contact name, email, optional phone, country, city and website; account status, submission times and verification/session records. Supplier name, focus and description are public. Other profile fields are restricted to the supplier and authorized staff.</li><li><strong>Contact inquiries:</strong> contact details, requirements and correspondence you choose to send. Previously submitted inquiries remain in the private staff inbox.</li><li><strong>Security:</strong> expiring session and sign-in token hashes, access controls, rate-limit buckets derived from connection addresses and minimal action logs.</li><li><strong>Listing reports:</strong> the notice, evidence, relevant contact details, decisions and correspondence needed to review a complaint.</li></ul><p>Article 6(1)(b) GDPR applies where processing is necessary for requested pre-contractual steps or performing an agreement with you. Article 6(1)(f) applies to legitimate interests in managing B2B representative communications, securing the service and handling reports, subject to balancing those interests against individual rights. Article 6(1)(c) may apply to legal obligations. Registration acknowledgment is not consent to marketing.</p></section><section><h2>Booking with Minup</h2><p>Clicking <a href="https://app.minup.io/book/stratevo" rel="noopener noreferrer" target="_blank">Book a Sourcing Call</a> opens Minup. The calendar is not embedded and is not contacted by this application before you follow the link. Booking details are processed through Minup and used by STRATEVO to arrange the requested meeting. Review <a href="https://minup.io/en/privacy-policy" target="_blank" rel="noopener noreferrer">Minup’s privacy policy</a> and its own cookie choices.</p></section><section><h2>Storage, service providers and notifications</h2><p>The hosting/database services store account and listing records. The configured email provider processes sign-in links and notifications; owner notifications can include submitted contact details. Authorized staff may use a configured notification webhook for those details, but never for authentication links. Staff must sign in to access private records. A queued email is not proof of delivery.</p><p>A browser backup contains only the public listing, never private contact fields or sign-in credentials. It is used to reconcile your listing with the server after you revisit. It does not restore lost private accounts or make temporary server storage durable. You can remove the backup in your supplier account or browser settings. See the <a href="/cookies">storage notice</a>.</p><p>The operator must confirm provider agreements, processing locations and any international-transfer safeguards for the actual hosting configuration. These are not established by the source code. Historical restricted records are not deleted merely by upgrading the website.</p></section><section><h2>Retention and your rights</h2><p>We retain records while needed for the account or requested sourcing work, complaint resolution and applicable legal obligations; necessity is reviewed when an account closes or a matter is resolved. Deletion must account for documented legal holds and backup cycles. The operator must finalize and apply a specific retention schedule; no automatic permanent-erasure guarantee is made.</p><p>Depending on applicable law, you may request access, rectification, erasure, restriction or portability, and object to processing based on legitimate interests. Where consent applies, you may withdraw it without affecting prior lawful processing. Contact <a href="mailto:info@stratevo.store">info@stratevo.store</a>. We may need proportionate identity verification. You may complain to the Hellenic Data Protection Authority or another competent supervisory authority. No marketing subscription is created by registration.</p></section></div>''')
save('cookies',heading('COOKIES & STORAGE','Essential functions. No advertising trackers.','Last updated 19 October 2026. This notice describes the application, not an audit of every setting in the hosting or booking provider.')+'<div class="readable legal">'+operator+'''<section><h2>Application storage inventory</h2><dl><dt>stratevo_session cookie</dt><dd>First-party HttpOnly, SameSite=Lax session cookie for supplier and staff authentication; eight-hour lifetime; Secure on hosted HTTPS. It is sent only to /api routes.</dd><dt>stratevo_supplier_public_v1 localStorage</dt><dd>A backup of the public supplier ID, name, focus and description, saved after successful registration or editing. It contains no private contact fields or authentication credentials. It is reconciled with an authenticated server record, expires after seven days when the application next reads it, and can be removed manually. Storage failure never blocks registration.</dd><dt>Page memory</dt><dd>Unsaved form values, request retry keys and open-menu state last only for the current page. They are not analytics records.</dd></dl><p>The application has no advertising pixels, third-party analytics, tracking embeds or cookie-consent overlay. Essential sign-in and the requested supplier-account recovery do not depend on accepting marketing cookies. Public browsing does not create a login session.</p></section><section><h2>External links</h2><p>Minup’s calendar opens only when you follow its link. Its website may use its own cookies and technologies, governed by its notices. No calendar, external fonts or social widgets are embedded here. Vasilis Krevatsoulis can be contacted at <a href="mailto:info@stratevo.store">info@stratevo.store</a> or <a href="tel:+306989472740">+30 6989472740</a>.</p></section><section><h2>Your controls</h2><p>Sign out to end the browser session. Use Clear Browser Backup in your supplier account or your browser’s site-data controls to remove the public backup. Blocking storage does not prevent server-side registration; blocking cookies prevents authenticated management. If optional tracking is added later, the storage inventory and consent requirements must be reviewed before activation.</p></section></div>''')
save('admin',heading('PRIVATE STAFF WORKSPACE','Supplier &amp; Operations Manager.','Sign in to review private contacts, supplier listings, notifications and existing inquiries.')+'''<section id="admin-login" class="panel narrow"><h2>Manager Sign In</h2><form id="admin-login-form" method="post">'''+field('username','Administrator name','autocomplete="username" value="owner"','admin')+field('password','Password or token','required type="password" maxlength="300" autocomplete="current-password"','admin')+field('otp','Authenticator code (only if configured)','inputmode="numeric" autocomplete="one-time-code" maxlength="6"','admin')+'''<button type="submit" class="primary">Sign In</button><p id="admin-login-status" role="status"></p></form><details><summary>First-time owner setup</summary><p>Set ADMIN_PASSWORD (at least 16 characters) or ADMIN_TOKEN (at least 32 characters) in the hosting environment, then redeploy when authorized. The alias login name is owner. ADMIN_TOTP_SECRET is optional and recommended; enter a current code only if configured. Named accounts can instead use ADMIN_ACCOUNTS_JSON. No default password or public access exists. Keep all credentials out of source code and chat.</p></details></section><section id="admin-workspace" hidden><button id="admin-logout" class="secondary" type="button">Sign Out</button><div id="content-studio"></div><div id="operations-manager"></div></section>''')
